'use strict';
async function render(){const version=++state.routeVersion,p=route();updateNav();$('.header').classList.remove('menu-open');$('.mobile-menu').setAttribute('aria-expanded','false');document.title=(p.startsWith('/community')?'Community':p==='/progress'?'My progress':p==='/profile'?'My profile':p==='/space'?'My space':p==='/ecosystem'?'The ecosystem':'Grow your own way')+' — Treksor';try{if(p==='/'){main.innerHTML=renderHome();return}if(p==='/ecosystem'){main.innerHTML=renderEcosystem();return}if(!db)fail('Connection unavailable. Please reload this page.');if(p.startsWith('/community')){const tab=p.endsWith('/one-to-one')?'buddy':p.endsWith('/mentors')?'mentors':'groups';main.innerHTML=communityShell(tab);await renderCommunity(tab,version);return}main.innerHTML='<div class="wrap section"><div class="loading">Preparing your space…</div></div>';if(p==='/space')await renderDashboard(version);else if(p==='/profile')await renderProfile(version);else if(p==='/progress')await renderProgress(version);else if(p.startsWith('/group/'))await renderGroup(p.split('/')[2],version);else if(p.startsWith('/connection/'))await renderConnection(p.split('/')[2],version);else if(p==='/admin')await renderAdmin(version);else main.innerHTML=pageTop('TREKSOR','A path still to be discovered.','Head home to find your next step.')+'<div class="wrap section"><a class="button" href="#/">Go home ↗</a></div>'}catch(e){if(version===state.routeVersion){const target=$('#community-results')||main;target.innerHTML=`<div class="wrap section"><div class="page-error"><h3>We could not load this space.</h3><p>${esc(errorText(e))}</p>${btn('Try again ↻','refresh','','ghost')}</div></div>`}}}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;if(el.tagName==='A'&&action==='close'){closeDialog();return}event.preventDefault();try{if(action==='menu'){const open=$('.header').classList.toggle('menu-open');el.setAttribute('aria-expanded',String(open))}else if(action==='close')closeDialog();else if(action==='login')authDialog();else if(action==='signup')authDialog('signup');else if(action==='profile')profileDialog();else if(action==='principles')principles();else if(action==='privacy')privacy();else if(action==='refresh'||action==='refresh-progress')await render();else if(action==='create-group')groupDialog();else if(action==='edit-group')groupDialog(await query(db.from('web_groups').select('*').eq('id',id).single()));else if(action==='practice'){const p=pillarData[Number(id)];openDialog(p.practice,`<div class="dialog-text"><p>${p.description}</p><ol>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol><a class="button" href="#/community" data-action="close">Share your next step ↗</a></div>`,p.name)}else if(action==='category'){state.filters.category=state.filters.category===id?'':id;await render()}else if(action==='clear-filters'){state.filters={q:'',city:'',category:''};await render()}else if(action==='invite')await inviteDialog(id);else if(action==='mentor-invite')await inviteDialog(id,'mentor');else if(action==='apply-mentor')await applyMentorDialog();else if(action==='mentor-detail')await mentorDetail(id);else if(action==='report-user')reportDialog(id);else if(action==='report-group')reportDialog(id,true);else if(action==='block-confirm')confirmDialog('Block this contact?','New invitations and messages between you will be disabled. You can unblock them in My space.','block',id);else if(action==='close-connection-confirm')confirmDialog('Close this connection?','New messages will be disabled. History is preserved. You cannot reopen it from the website.','close-connection',id);else if(action==='delete-group-confirm')confirmDialog('Delete this group?','The group, memberships and conversations will be permanently deleted.','delete-group',id);else if(action==='reject-mentor-confirm')confirmDialog('Remove this mentor application?','The mentor profile will no longer appear. The account and conversation history will remain.','reject-mentor',id);else{el.disabled=true;if(action==='logout'){const {error}=await db.auth.signOut();if(error)throw error;state.user=null;state.profile=null;state.admin=false;state.device='';++state.routeVersion;go('/');toast('Signed out.')}else if(action==='join-group'){if(!needProfile())return;await query(db.from('web_group_members').insert({group_id:id,user_id:state.user.id}));toast('You have joined the group.');await render()}else if(action==='leave-group'){await query(db.from('web_group_members').delete().eq('group_id',id).eq('user_id',state.user.id));toast('You have left the group.');await render()}else if(['accept','decline','close-connection'].includes(action)){const status=action==='accept'?'accepted':action==='decline'?'declined':'closed';await query(db.from('web_connections').update({status}).eq('id',id).select('id').single());closeDialog();toast(statusLabels[status]);await render()}else if(action==='block'){await query(db.from('web_blocks').insert({blocker_id:state.user.id,blocked_id:id}));closeDialog();toast('Contact blocked.');await render()}else if(action==='unblock'){await query(db.from('web_blocks').delete().eq('blocker_id',state.user.id).eq('blocked_id',id));toast('Contact unblocked.');await render()}else if(action==='withdraw-mentor'){await query(db.from('web_mentors').delete().eq('user_id',state.user.id));closeDialog();toast('Mentor profile withdrawn.');await render()}else if(action==='approve-mentor'){await query(db.from('web_mentors').update({approved:true}).eq('user_id',id).select('user_id').single());toast('Mentor profile published.');await render()}else if(action==='reject-mentor'){await query(db.from('web_mentors').delete().eq('user_id',id));closeDialog();toast('Mentor application removed.');await render()}else if(action==='resolve-report'){await query(db.from('web_reports').update({resolved:true}).eq('id',id).select('id').single());toast('Report marked as reviewed.');await render()}else if(action==='delete-group'){await query(db.from('web_groups').delete().eq('id',id).select('id').single());closeDialog();toast('Group deleted.');go(state.admin?'/admin':'/space')}}}catch(e){toast(errorText(e))}finally{el.disabled=false}});
document.addEventListener('submit',async event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const data=new FormData(form),val=name=>String(data.get(name)||'').trim(),button=$('button[type=submit]',form),error=$('.form-error',form);if(error)error.textContent='';if(button)button.disabled=true;try{
if(form.id==='filters'){state.filters={q:val('q').replace(/[%_]/g,''),city:val('city').replace(/[%_]/g,''),category:val('category')};await render()}
else if(form.id==='auth-form'){const signup=state.dialogContext?.mode==='signup',email=val('email'),password=String(data.get('password')||'');const result=signup?await db.auth.signUp({email,password,options:{data:{name:val('name'),display_name:val('name'),adult_confirmed:true}}}):await db.auth.signInWithPassword({email,password});if(result.error)throw result.error;if(signup&&!result.data.session)openDialog('Check your email.',`<div class="dialog-text"><p>If registration can be completed, you will receive a confirmation email. Follow the link, then return here to sign in.</p><p>Already registered? Sign in with your existing account.</p>${btn('Back to sign in','login')}</div>`);else{state.user=result.data.user;await loadProfile();closeDialog();go('/space');toast('Welcome to Treksor.')}}
else if(form.id==='account-form'){const uid=state.user.id;let avatar_url=state.user.user_metadata?.avatar_url||'';const photo=data.get('photo');if(photo instanceof File&&photo.size){if(!['image/jpeg','image/png','image/webp'].includes(photo.type))fail('Choose a JPG, PNG or WebP photo.');if(photo.size>5*1024*1024)fail('Choose a photo smaller than 5 MB.');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[photo.type],path=uid+'/avatar-web-'+Date.now()+'.'+ext;const result=await db.storage.from('profile-avatars').upload(path,photo,{contentType:photo.type,cacheControl:'3600',upsert:false});if(result.error)throw result.error;avatar_url=db.storage.from('profile-avatars').getPublicUrl(path).data.publicUrl}if(state.user?.id!==uid)fail('Your session changed. Please sign in again.');const result=await db.auth.updateUser({data:{name:val('name'),avatar_url}});if(result.error)throw result.error;state.user=result.data.user;toast('Profile saved for the app and website.');await render()}
else if(form.id==='profile-form'){const payload={user_id:state.user.id,display_name:val('display_name'),city:val('city'),bio:val('bio'),pace:val('pace'),interests:data.getAll('interests'),discoverable:data.has('discoverable')};if(state.profile){const {user_id,...fields}=payload;await query(db.from('web_profiles').update(fields).eq('user_id',user_id).select().single())}else await query(db.from('web_profiles').insert(payload).select().single());await loadProfile();closeDialog();toast('Community profile saved.');await render()}
else if(form.id==='group-form'){const payload={title:val('title'),description:val('description'),category:val('category'),city:val('city'),size_style:val('size_style'),next_activity:val('next_activity')},editing=state.dialogContext?.group;const group=editing?await query(db.from('web_groups').update(payload).eq('id',editing.id).select().single()):await query(db.from('web_groups').insert({...payload,owner_id:state.user.id}).select().single());closeDialog();toast(editing?'Group updated.':'Your group is ready.');go('/group/'+group.id)}
else if(form.id==='invite-form'){const {id,kind}=state.dialogContext,c=await query(db.from('web_connections').insert({from_user:state.user.id,to_user:id,kind,introduction:val('introduction')}).select().single());closeDialog();toast('Invitation sent within Treksor.');go('/connection/'+c.id)}
else if(form.id==='mentor-form'){await query(db.from('web_mentors').insert({user_id:state.user.id,headline:val('headline'),specialty:val('specialty'),format:val('format'),description:val('description'),experience:val('experience')}));closeDialog();toast('Application received and awaiting review.');go('/space')}
else if(form.id==='post-form'){await query(db.from('web_group_posts').insert({group_id:form.dataset.id,user_id:state.user.id,body:val('body')}));toast('Posted to the group.');await render()}
else if(form.id==='message-form'){await query(db.from('web_messages').insert({connection_id:form.dataset.id,sender_id:state.user.id,body:val('body')}));toast('Message sent.');await render()}
else if(form.id==='report-form'){const {id,group}=state.dialogContext;await query(db.from('web_reports').insert({reporter_id:state.user.id,target_user:group?null:id,target_group:group?id:null,reason:val('reason')}));closeDialog();toast('Report received by Treksor.')}
}catch(e){if(error)error.textContent=errorText(e);else toast(errorText(e))}finally{if(button)button.disabled=false}});
document.addEventListener('change',e=>{if(e.target.id==='device-select'){state.device=e.target.value;render()}if(e.target.id==='period-select'){state.period=Number(e.target.value);render()}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
window.addEventListener('hashchange',()=>{closeDialog();state.filters={q:'',city:'',category:''};window.scrollTo(0,0);render()});
$('#year').textContent=new Date().getFullYear();
setInterval(()=>{if(state.user&&route()==='/progress'&&document.visibilityState==='visible'&&!$('#dialog').open)renderProgress(state.routeVersion).catch(()=>toast('Progress refresh paused. Please try Refresh progress.'))},60000);
(async()=>{await render();if(!db)return;try{const {data,error}=await db.auth.getSession();if(error)throw error;state.user=data.session?.user||null;await loadProfile();if(state.user)await render()}catch{toast('We could not restore your session. Please sign in again.')}db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){state.user=null;state.profile=null;state.admin=false;state.device='';++state.routeVersion;setTimeout(render,0)}else if(event==='SIGNED_IN'&&session?.user?.id!==state.user?.id){state.user=session.user;state.device='';++state.routeVersion;setTimeout(async()=>{try{await loadProfile();await render()}catch(e){toast(errorText(e))}},0)}else if(event==='USER_UPDATED'&&session?.user?.id===state.user?.id){state.user=session.user}})})();
